+const express = require('express');
+const helmet = require('helmet');
+const cors = require('cors');
+const rateLimit = require('express-rate-limit');
+const xss = require('xss-clean');
+const morgan = require('morgan');
+const Joi = require('joi');               // validation library
+const createError = require('http-errors'); // helpful for 404/500 errors
+
+const app = express();
+
+/* --------------------------- Middleware stack --------------------------- */
+
+// 1. Basic security headers
+app.use(helmet());
+
+// 2. Enable CORS – restrict to trusted origins in production
+const corsOptions = {
+  origin: process.env.CORS_ORIGIN?.split(',') || '*', // e.g. "https://myapp.com,https://admin.myapp.com"
+  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
+  allowedHeaders: ['Content-Type', 'Authorization'],
+};
+app.use(cors(corsOptions));
+
+// 3. Rate limiting – prevents brute‑force and DoS attacks
+const limiter = rateLimit({
+  windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS, 10) || 15 * 60 * 1000, // 15 min
+  max: parseInt(process.env.RATE_LIMIT_MAX, 10) || 100,                    // limit each IP
+  standardHeaders: true,
+  legacyHeaders: false,
+});
+app.use(limiter);
+
+// 4. Body parsing (JSON) – limit payload size to 10 KB (adjust as needed)
+app.use(express.json({ limit: '10kb' }));
+
+// 5. Basic XSS protection for any string fields that later touch HTML
+app.use(xss());
+
+// 6. HTTP request logging – switch to 'combined' in production for more details
+app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));
+
+/* ------------------------------- Routes ------------------------------- */
+
+// Health‑check – no authentication needed; returns a tiny JSON payload
+app.get('/health', (req, res) => {
+  res.json({ status: 'ok', timestamp: new Date().toISOString() });
+});
+
+/** --------------------------------------------------------------------
+ *  Example: /users endpoint
+ *  • Currently returns a static list.
+ *  • Shows how you could validate optional query parameters (e.g. pagination)
+ * --------------------------------------------------------------------
+ */
+// Validation schema for query parameters (here just a placeholder)
+const usersQuerySchema = Joi.object({
+  page: Joi.number().integer().min(1).default(1),
+  limit: Joi.number().integer().min(1).max(100).default(10),
+});
+
+app.get('/users', (req, res, next) => {
+  // ----------- Input validation (if you ever accept query params) ---------
+  const { error, value: validated } = usersQuerySchema.validate(req.query);
+  if (error) {
+    // Bad request – we don’t expose Joi details to the client, just a generic message
+    return next(createError(400, 'Invalid query parameters'));
+  }
+
+  // ----------- Business logic (static for now) ---------------------------
+  // In a real app you would use `validated.page` / `validated.limit` to
+  // paginate results from a DB. Keeping the static array for the demo.
+  const users = [
+    { id: 1, name: 'Alice', email: 'alice@example.com' },
+    { id: 2, name: 'Bob', email: 'bob@example.com' },
+  ];
+  res.json(users);
+});
+
+/* -------------------------- 404 handling -------------------------- */
+// Any route not matched above falls through to this handler
+app.use((req, res, next) => {
+  next(createError(404, 'Resource not found'));
+});
+
+/* ------------------------ Central error handler ------------------------ */
+app.use((err, req, res, next) => {
+  // Log the error – in a real service you might forward this to a log aggregation
+  // service (e.g. Winston, Bunyan, Pino, or a cloud provider).
+  console.error(err);
+
+  const status = err.status || 500;
+  const response = {
+    error: {
+      // Do **not** leak internal stack traces to the client in production
+      message: process.env.NODE_ENV === 'production'
+        ? (status >= 500 ? 'Internal Server Error' : err.message)
+        : err.message,
+      // Optional: include the code for machine‑readable clients
+      code: err.status || 500,
+    },
+  };
+
+  // In development we add the stack for easier debugging
+  if (process.env.NODE_ENV !== 'production') {
+    response.error.stack = err.stack;
+  }
+
+  res.status(status).json(response);
+});
+
+/* ------------------------ Server bootstrap (optional) ------------------------ */
+/**
+ *  We export the `app` for testing **without** starting the HTTP listener.
+ *  When the file is executed directly (`node app.js`) we start the server.
+ *  This pattern prevents the server from listening during `require('./app')`
+ *  in unit‑tests or when the app is embedded in a larger system (e.g. serverless).
+ */
+if (require.main === module) {
+  const PORT = process.env.PORT || 3000;
+  const server = app.listen(PORT, () => {
