app.use(express.json({ limit: '10kb' }));  // parse JSON bodies, limit size
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));
```

* **Helmet** adds a solid collection of HTTP headers that mitigate XSS, click‑jacking, MIME‑sniffing, etc.  
* **CORS** is explicitly configured; in production you should replace `'*'` with an allow‑list.  
* **express.json** with a size limit stops huge payload attacks.  
* **Morgan** gives you structured logs without leaking stack traces.

### 2.2 Rate Limiting
```js
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,   // 15 minutes
  max: 100,                   // limit each IP to 100 requests per window
  standardHeaders: true,     // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false,
});
app.use('/users', apiLimiter);   // apply to any endpoint that might become expensive
// You could also do `app.use(apiLimiter);` to protect the whole API.
```

### 2.3 Centralised Error‑Handling Middleware
```js
// Catch‑all async wrapper (optional helper)
const asyncWrap = fn => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Example of using asyncWrap when you add async routes later
// app.get('/something', asyncWrap(async (req, res) => { … }));

// Global error handler – always the last middleware
app.use((err, req, res, next) => {
  // Log the error (you may replace console.error with a logger)
  console.error(err);

  // Do NOT leak stack traces or internal messages in production
  const status = err.status || 500;
  const message = (process.env.NODE_ENV === 'production')
    ? 'Internal Server Error'
    : err.message;

  res.status(status).json({ error: message });
});
```

* This guarantees **any** uncaught exception returns a controlled JSON response and never crashes the process.  
* In production you hide implementation details while still logging them server‑side.

### 2.4 Validate Future Input (Query / Body)

Even though the current routes have no user input, it’s best to set up a reusable validation pipeline now:

```js
const { celebrate, Joi, errors, Segments } = require('celebrate'); // npm i celebrate

// Example: validate query parameters for a future `/users` filter endpoint
app.get(
  '/users',
  celebrate({
    [Segments.QUERY]: Joi.object({
      limit: Joi.number().integer().min(1).max(100).default(20),
      offset: Joi.number().integer().min(0).default(0),
      sortBy: Joi.string().valid('id', 'name', 'email').default('id')
    })
  }),
  (req, res) => {
    // At this point req.query is guaranteed to conform to the schema
    const { limit, offset, sortBy } = req.query;
    // …implementation…
    res.json([...]); // unchanged sample data
  }
);

// Celebrate's error‑handler – must be added **after** your routes, before the generic error handler
app.use(errors());
```

* **Celebrate/Joi** provides a declarative schema; any malformed request results in a `400 Bad Request` with a clear message.  
* If you prefer another validator (express‑validator, yup, zod, etc.) the pattern is identical.

