const helmet    = require('helmet');
const cors      = require('cors');
const rateLimit = require('express-rate-limit');
const morgan    = require('morgan');
const { body, query, validationResult } = require('express-validator');

// ---------------------------------------------------------------------------
// App initialization
// ---------------------------------------------------------------------------
const app = express();

// ---------------------------------------------------------------------------
// Security / utility middleware
// ---------------------------------------------------------------------------

// Remove the default X‑Powered‑By header (information disclosure)
app.disable('x-powered-by');

// Helmet sets a sensible collection of HTTP security headers
app.use(helmet());

// CORS – only allow origins you trust.  For a pure internal API you can disable it.
app.use(
  cors({
    origin: process.env.ALLOWED_ORIGINS?.split(',') || false, // e.g. "https://example.com"
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    credentials: true,
  })
);

// Rate limiting – 100 requests per 15‑minute window per IP
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false,
});
app.use('/users', apiLimiter);   // Apply only where you expect traffic
app.use('/health', apiLimiter); // optional – health checks are cheap

// Body parser – limit JSON payload size to 1 MB
app.use(express.json({ limit: '1mb' }));

// Structured request logging (use 'combined' in production)
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// Health endpoint – no user‑supplied data, simple JSON response
