 * GET /users
 *   – In a real app you’d fetch data from a DB.
 *   – Demonstrates input validation (optional query param `id`).
 */
app.get(
  '/users',
  // -------------- validation chain --------------
  // Example: allow a numeric `id` query param to filter a user
  query('id')
    .optional()
    .isInt({ min: 1 })
    .withMessage('id must be a positive integer')
    .toInt(),
  // -------------- handler -----------------------
  (req, res, next) => {
    try {
      // Check validation result early
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        // 400 Bad Request – client sent malformed input
        return res.status(400).json({ errors: errors.array() });
      }

      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // If an `id` filter was supplied, return the matching user only
      if (req.query.id) {
        const filtered = users.find(u => u.id === req.query.id);
        if (!filtered) {
          return res.status(404).json({ message: 'User not found' });
        }
        return res.json(filtered);
      }

      // Default: return the full list
      res.json(users);
    } catch (err) {
      // Forward unexpected errors to the centralized error handler
      next(err);
    }
  }
);

// ---------------------------------------------------------------------------
// 404 – Route not found
// ---------------------------------------------------------------------------
app.use((req, res, next) => {
  res.status(404).json({ error: 'Not found' });
});

// ---------------------------------------------------------------------------
// Centralized error handler
// ---------------------------------------------------------------------------
app.use((err, req, res, next) => {
  // Log the full error (stack trace) – using console here; replace with winston/etc.
  console.error(err);

  // Do **not** expose internal details in production
  const isProd = process.env.NODE_ENV === 'production';
  const status = err.status || 500;
  const response = {
    error: isProd ? 'Internal server error' : err.message,
  };
  if (!isProd && err.stack) {
    response.stack = err.stack;
  }

  res.status(status).json(response);
});

// ---------------------------------------------------------------------------
// Server start – use env var for port, default to 3000
// ---------------------------------------------------------------------------
if (require.main === module) { // allows `require('./app')` without auto‑listen
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });
}

module.exports = app;
