const server = app.listen(PORT, () => {
  logger.info(`🚀 Server listening on port ${PORT}`);
});

function gracefulShutdown() {
  logger.info('🔁 Graceful shutdown initiated');
  server.close(() => {
    logger.info('🛑 HTTP server closed');
