### B. Centralised error handling
Create `middleware/errorHandlers.js`:

```js
// middleware/errorHandlers.js
function notFoundHandler(req, res, next) {
  const err = new Error('Not Found');
  err.status = 404;
  next(err);
}

// Generic error catcher – never expose stack traces in production
function errorHandler(err, req, res, next) {
  const status = err.status || 500;
  const response = {
    error: {
      message: status === 500 ? 'Internal Server Error' : err.message,
    },
  };
  // Log the full error for internal diagnostics
  console.error(err);
  res.status(status).json(response);
}

module.exports = { notFoundHandler, errorHandler };
```

*Why?*  
- Guarantees a JSON response for every error.  
- Prevents accidental leaking of stack traces or internal details to a client.  

