  { id: 2, name: 'Bob',   email: 'bob@example.com' },
];

/**
 * GET /users – public list (no validation needed)
 */
router.get('/', (req, res) => {
  res.json(users);
});

/**
 * POST /users – create a new user
 * Validation rules:
 *   • name: required, string, trimmed, 1‑100 chars
 *   • email: required, must be a valid email, normalized
 */
router.post(
  '/',
  [
    body('name')
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters.'),
    body('email')
      .isEmail()
      .withMessage('Invalid email address.')
      .normalizeEmail(),
  ],
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      // 400 Bad Request with detailed validation messages
      return res.status(400).json({ errors: errors.array() });
    }

    const { name, email } = req.body;
    const newUser = {
      id: users.length + 1,
      name,
      email,
    };
    users.push(newUser);
    res.status(201).json(newUser);
  }
);

/**
 * GET /users/:id – fetch a single user
 * Validate that :id is a positive integer.
 */
router.get(
  '/:id',
  [param('id').isInt({ gt: 0 }).toInt()],
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const user = users.find(u => u.id === req.params.id);
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }
    res.json(user);
  }
);

module.exports = router;
```

And expose it from `routes/index.js`:

```js
// routes/index.js
const express = require('express');
const usersRouter = require('./users');
const healthRouter = require('express').Router();

healthRouter.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

const router = express.Router();
router.use('/health', healthRouter);
router.use('/users', usersRouter);

module.exports = router;
```

**Why this matters**

* **`express-validator`** (or a schema validator like `joi`) ensures that any data entering the system conforms to the shape you expect, eliminating injection vectors (e.g., NoSQL/SQL injection, XSS payloads in stored data).  
* Sanitising / normalising (e.g., `normalizeEmail()`) prevents subtle encoding tricks.  
* Validation errors are returned with **400 Bad Request**, keeping the API contract clear.

---

## 4️⃣ Additional production‑ready hardening tips

| Topic | Action |
|-------|--------|
| **HTTPS** | Deploy behind a TLS terminator (NGINX, load balancer) or use `express-sslify` to force `https://` in production. |
| **Content Security Policy** | Configure a restrictive CSP via `helmet.contentSecurityPolicy`. |
| **Cookie security** | If you ever add cookies, set `httpOnly`, `secure`, and `sameSite='strict'`. |
| **Dependency health** | Run `npm audit --production` CI step and address any high‑severity findings. |
| **Process crash safety** | Run the app under a process manager (`pm2`, Docker, systemd) that restarts on failures. |
| **Logging** | Replace `console.log` / `console.error` with a structured logger (Winston/Pino) that writes to a file or log aggregation service. |
| **Graceful shutdown** | Listen for `SIGTERM`/`SIGINT` and close the server and DB connections before exiting. |
| **Static analysis** | Use tools like `eslint` with the `security` plugin (`eslint-plugin-security`) to catch common pitfalls. |
| **Rate‑limit per route** | For auth endpoints, apply stricter rate limits (e.g., 5 attempts per minute). |
| **Helmet CSP nonce** | If you ever serve HTML, generate a per‑request nonce and include it in the CSP header. |

---

## 5️⃣ TL;DR – Quick “drop‑in” diff for your current file

If you just want a minimal change without restructuring the whole project, you can add the following **top‑level middleware** right after the `express()` line:

```js
// Add near the top of app.js
const helmet     = require('helmet');
const cors       = require('cors');
const rateLimit  = require('express-rate-limit');
const morgan     = require('morgan');

// Security middleware
app.use(helmet());                     // security headers
app.use(cors({ origin: process.env.CORS_ORIGIN?.split(',') || [] }));
app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100,
    message: { error: 'Too many requests' },
  })
);
app.use(morgan('combined'));
app.use(express.json());

// 404 & error handling (add at the bottom, before `module.exports`)
app.use((req, res) => res.status(404).json({ error: 'Not Found' }));
app.use((err, req, res, next) => {
  console.error(err);
  const status = err.statusCode || 500;
  const payload = { error: err.message || 'Internal Server Error' };
  if (process.env.NODE_ENV !== 'production') payload.stack = err.stack;
  res.status(status).json(payload);
});
```

Then run:

```bash
npm install helmet cors express-rate-limit morgan
```

