const rateLimit = require('express-rate-limit');
const cors = require('cors');

// Helmet sets a solid default set of security headers.
app.use(helmet());

// Simple global rate limiter (adjust as needed).
const limiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 100,            // max 100 requests per IP per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Restrict CORS to trusted origins (empty array = no cross‑origin access)
app.use(
  cors({
    origin: process.env.CORS_ORIGINS?.split(',') || [], // e.g. "https://myapp.com,https://admin.myapp.com"
    methods: ['GET'],
    allowedHeaders: ['Content-Type', 'Authorization'],
  })
