// ──────────────────────────────────────────────────────────────────────────────
// 3rd‑party modules
// ──────────────────────────────────────────────────────────────────────────────
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');               // request logging
const { query, validationResult } = require('express-validator'); // example validator

// ──────────────────────────────────────────────────────────────────────────────
// App initialisation
// ──────────────────────────────────────────────────────────────────────────────
const app = express();

// ----- Basic security hardening ------------------------------------------------
app.disable('x-powered-by');          // hide Express fingerprint
app.use(helmet());                    // set security‑related HTTP headers

// ----- CORS (adjust whitelist as needed) ---------------------------------------
app.use(
  cors({
    origin: ['https://my‑frontend.com'], // <-- replace with your allowed origins
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    credentials: true,
  })
);

// ----- Rate limiting (global) --------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 min
  max: 100,                // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ----- Body parser with size limits --------------------------------------------
app.use(express.json({ limit: '1kb' }));   // tighten according to your API needs

// ----- Request logging ----------------------------------------------------------
app.use(morgan('combined')); // or 'dev' for development

// ──────────────────────────────────────────────────────────────────────────────
// Helper: async wrapper (captures async rejections)
// ──────────────────────────────────────────────────────────────────────────────
const asyncWrapper = (fn) => (req, res, next) =>
  Promise.resolve(fn(req, res, next)).catch(next);

// ──────────────────────────────────────────────────────────────────────────────
// Routes
// ──────────────────────────────────────────────────────────────────────────────
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Example shows how to plug in validation if you later accept query params.
 * Currently it just returns static data.
 */
app.get(
  '/users',
  // Example validation chain – remove or extend as you add real parameters
  [
    query('page')
      .optional()
      .isInt({ min: 1 })
      .toInt()
      .withMessage('page must be a positive integer'),
  ],
  asyncWrapper(async (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // In a real implementation you would fetch from DB here
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Example pagination (if you later implement it)
    // const { page = 1 } = req.query;
    // const paged = users.slice((page - 1) * 10, page * 10);

    res.json(users);
  })
);

// ──────────────────────────────────────────────────────────────────────────────
// Centralized error‑handling middleware
// ──────────────────────────────────────────────────────────────────────────────
function errorHandler(err, req, res, _next) {
  // Log the full error (stack) – in production you may want a logger like Winston
  console.error(err);

  // Avoid leaking internal details – expose only safe message for 5xx errors
  const status = err.status || 500;
  const response = {
    error:
      status >= 500
        ? 'Internal Server Error'
        : err.message || 'Bad Request',
  };

  // If you have a custom error class you can attach a code, etc.
  res.status(status).json(response);
}
app.use(errorHandler);

// ──────────────────────────────────────────────────────────────────────────────
// Server start / graceful shutdown
// ──────────────────────────────────────────────────────────────────────────────
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`🚀 Server listening on http://localhost:${PORT}`);
});

// Graceful shutdown
function gracefulShutdown() {
  console.log('\n🛑 Received shutdown signal – closing server...');
  server.close(() => {
    console.log('🧹 Server closed. Exiting process.');
    process.exit(0);
  });

  // Force exit after 10 seconds (in case of hanging connections)
  setTimeout(() => {
    console.error('⚠️ Forcefully terminating after timeout');
    process.exit(1);
  }, 10_000).unref();
}
process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

// Process‑wide exception handling (log + exit)
process.on('unhandledRejection', (reason) => {
  console.error('❗ Unhandled Promise Rejection:', reason);
  // Optionally trigger gracefulShutdown() here
});
process.on('uncaughtException', (err) => {
  console.error('❗ Uncaught Exception:', err);
  process.exit(1); // exit because the state may be compromised
});

module.exports = app; // kept for unit‑tests
```

